INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(5401, 'Deuteronomy 34:6', 'Deuteronomy', 34, 6, '&nbsp;نو هغۀ هغه د بيت‌فعور ښار ته مخامخ د موآب په مُلک کښې په يو مېدان کښې ښخ کړو، خو تر ننه پورې د هغۀ د ښخېدو صحيح ځائ پته هيچا ته نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5402, 'Deuteronomy 34:7', 'Deuteronomy', 34, 7, '&nbsp;موسىٰ د يو سل او شلو کالو په عُمر کښې وفات شو، هغه په هغه وخت هم د مخکښې په شان تکړه وو او د هغۀ د سترګو نظر ټيک وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5403, 'Deuteronomy 34:8', 'Deuteronomy', 34, 8, '&nbsp;بنى اِسرائيل دېرش ورځې د موآب په مېدانونو کښې په هغۀ پسې غمژن وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5404, 'Deuteronomy 34:9', 'Deuteronomy', 34, 9, '&nbsp;د نون زوئ يشوَع د اِلهامى حِکمت نه ډک شو، ځکه چې موسىٰ هغه مقرر کړے وو چې د هغۀ په ځائ کار کوى. بنى اِسرائيلو د يشوَع تابعدارى وکړه او هغه حُکمونه يې پوره کړل چې مالِک خُدائ د موسىٰ په ذريعه هغوئ له ورکړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5405, 'Deuteronomy 34:10', 'Deuteronomy', 34, 10, '&nbsp;نو په اِسرائيلو کښې هيڅکله د موسىٰ په شان پېغمبر نۀ دے پېدا شوے، چې مالِک خُدائ مخامخ د هغۀ سره خبرې وکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5406, 'Deuteronomy 34:11', 'Deuteronomy', 34, 11, '&nbsp;مالِک خُدائ موسىٰ د دې دپاره مُلک مِصر ته ولېږلو چې د فِرعون او د هغۀ د درباريانو خلاف داسې معجزې او عجيبه کارونه ښکاره کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5407, 'Deuteronomy 34:12', 'Deuteronomy', 34, 12, '&nbsp;بل يو پېغمبر هم داسې لوئ لوئ او يروونکى کارونه نۀ دى کړى لکه چې موسىٰ د ټولو بنى اِسرائيلو په وړاندې وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5408, 'Joshua 1:1', 'Joshua', 1, 1, '&nbsp;د مالِک خُدائ خِدمت کوونکى موسىٰ د مرګ نه پس مالِک خُدائ د موسىٰ مددګار د نون زوئ يشوَع سره کلام وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5409, 'Joshua 1:2', 'Joshua', 1, 2, '&nbsp;هغۀ وفرمائيل، ”زما خِدمت کوونکے موسىٰ مړ دے نو اوس تۀ او اِسرائيليان تيار شئ او د اُردن د سيند نه پورې غاړه هغه زمکې ته واوړئ چې زۀ به يې تاسو له درکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5410, 'Joshua 1:3', 'Joshua', 1, 3, '&nbsp;چې زۀ به هر هغه ځائ تاسو له درکوم چې چرته تاسو قدم ږدئ هم هغه شان لکه څنګه چې ما د موسىٰ سره وعده کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5411, 'Joshua 1:4', 'Joshua', 1, 4, '&nbsp;ستاسو علاقه به په جنوب کښې د بيابان نه واخله په شمال کښې د لبنان غرونو پورې، نمرخاتۀ طرف د فرات د لوئ سيند نه واخله، نمرپرېواتۀ طرف ته د مديترانى د سمندر پورې خوره وى چې په دې کښې به د حِتيانو ټول مُلک شامل وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5412, 'Joshua 1:5', 'Joshua', 1, 5, '&nbsp;يشوَع چې تر کومې پورې تۀ ژوندے يې هيڅ څوک به تا له شکست نۀ شى درکولے. زۀ به ستا هغه شان مل يم لکه څنګه چې د موسىٰ مل وم. زۀ به کله هم تاسو سره بې‌وفائى ونۀ کړم او نۀ به مو يواځې پرېږدم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5413, 'Joshua 1:6', 'Joshua', 1, 6, '&nbsp;تکړه او زړَور اوسه ځکه کله چې دوئ هغه زمکه قبضه کوى نو تۀ به د هغوئ مشر يې، هغه زمکه چې ما د دوئ پلار نيکۀ سره د هغې لوظ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5414, 'Joshua 1:7', 'Joshua', 1, 7, '&nbsp;تکړه او زړَور اوسه او په هغه ټول شريعت باندې عمل کوه چې زما خِدمت کوونکى موسىٰ تا له درکړے دے. د هغې نه يو خوا بل خوا مۀ اوړه او بيا چې هر چرته هم تۀ ځې نو کامياب به يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5415, 'Joshua 1:8', 'Joshua', 1, 8, '&nbsp;ستاسو په خولۀ دې د شريعت دا کِتاب خبرې همېشه وى. شپه او ورځ په دې غور کوئ. او چې په دې کښې څۀ ليکلى دى نو په هغې ښۀ عمل کوئ. نو تاسو به کامياب يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5416, 'Joshua 1:9', 'Joshua', 1, 9, '&nbsp;دا ياد ساته چې ما تا ته حُکم کړے وو چې تکړه او زړَور اوسه. يرېږه مه او چې بې‌حوصلې نۀ شې، ځکه چې تۀ هر چرته هم ځې نو زۀ مالِک خُدائ ستا خُدائ پاک به ستا مل يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5417, 'Joshua 1:10', 'Joshua', 1, 10, '&nbsp;بيا يشوَع مشرانو له حُکم ورکړو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5418, 'Joshua 1:11', 'Joshua', 1, 11, '&nbsp;”په کېمپ کښې وګرځئ او خلقو ته ووايئ چې، څۀ خوراک تيار کړئ ځکه چې درې ورځې پس به تاسو د اُردن سيند نه واوړئ او هغه مُلک به قبضه کړئ چې مالِک خُدائ ستاسو خُدائ پاک يې تاسو له درکوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5419, 'Joshua 1:12', 'Joshua', 1, 12, '&nbsp;يشوَع د روبين، جاد او د منسى نيمې قبيلې ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5420, 'Joshua 1:13', 'Joshua', 1, 13, '&nbsp;”هغه څۀ مۀ هېروئ چې د مالِک خُدائ خِدمت کوونکى موسىٰ تاسو ته فرمائيلى وُو چې، ”مالِک خُدائ ستاسو خُدائ پاک به تاسو له د آرام ځائ درکړى او هغه به تاسو له دا زمکه درکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5421, 'Joshua 1:14', 'Joshua', 1, 14, '&nbsp;ستاسو ښځې، ماشومان او څاروى به په هغه زمکه باندې پاتې شى چې موسىٰ د اُردن سيند بلې غاړې ته تاسو له درکړې ده. خو ستاسو تکړه لښکر به سره د وسلې د بنى اِسرائيلو وروڼو د مدد دپاره مخکښې روان وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5422, 'Joshua 1:15', 'Joshua', 1, 15, '&nbsp;تر دې چې مالِک خُدائ هغوئ او تاسو له هم آرام درکړى او چې هغوئ هغه زمکه ونيسى چې مالِک خُدائ ستاسو خُدائ پاک هغوئ له ورکړې ده. نو بيا به تاسو خپل هغه مُلک ته راشئ او قبضه به يې کړئ چې د اُردن سيند نه اخوا نمرخاتۀ طرف ته دے، کوم چې د مالِک خُدائ خِدمت کوونکى موسىٰ تاسو له درکړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5423, 'Joshua 1:16', 'Joshua', 1, 16, '&nbsp;هغوئ يشوَع ته ووئيل، ”مونږ به هغه هر څۀ کوُو چې تۀ يې مونږ ته حُکم کوې او هر چرته مو چې لېږې نو مونږ به ځُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5424, 'Joshua 1:17', 'Joshua', 1, 17, '&nbsp;مونږ به ستا په خبره عمل کوُو لکه څنګه مو چې همېشه د موسىٰ خبره منلې ده. او مالِک خُدائ ستا خُدائ پاک دې ستا هغه شان مل وى لکه څنګه چې هغه د موسىٰ مل وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5425, 'Joshua 1:18', 'Joshua', 1, 18, '&nbsp;او څوک هم چې ستا د حُکمونو نه بغاوت کوى او ستا په خبرو باندې عمل نۀ کوى نو مړ به کړے شى. نو بس تۀ تکړه او زړَور اوسه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5426, 'Joshua 2:1', 'Joshua', 2, 1, '&nbsp;بيا يشوَع د شطيم کېمپ نه دوه جاسوسان په پټه ولېږل او دوئ ته يې حُکم ورکړو چې، ”لاړ شئ او د کنعان په حقله معلومات حاصل کړئ او خاص کَر د يريحو ښار په حقله.“ کله چې هغوئ هغه ښار ته ورغلل نو لاړل چې د راحب نومې کنجرې کره شپه وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5427, 'Joshua 2:2', 'Joshua', 2, 2, '&nbsp;د يريحو بادشاه خبر شو چې څۀ اِسرائيليان په هغه شپه د دې مُلک د جاسوسۍ دپاره راغلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5428, 'Joshua 2:3', 'Joshua', 2, 3, '&nbsp;نو هغۀ راحب ته پېغام ولېږلو، ”ستا کور کښې چې کوم سړى دى هغه د دې مُلک معلومات حاصلولو له راغلى دى. هغوئ رابهر کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5429, 'Joshua 2:7', 'Joshua', 2, 7, '&nbsp;د بادشاه سړى د ښار نه لاړل او بيا د ښار دروازه بنده شوه. هغوئ د بنى اِسرائيلو جاسوسانو پسې تر هغه ځائ پورې لاړل چرته چې سړک د اُردن سيند نه تېريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5430, 'Joshua 2:8', 'Joshua', 2, 8, '&nbsp;د جاسوسانو د څملاستو نه مخکښې راحب چت ته وروخته', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5431, 'Joshua 2:9', 'Joshua', 2, 9, '&nbsp;او ورته يې ووئيل، ”ما ته پته ده چې مالِک خُدائ دا مُلک تاسو له درکړے دے او د دې مُلک هر يو کس تاسو نه سخت يريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5432, 'Joshua 2:10', 'Joshua', 2, 10, '&nbsp;مونږ د هغې نه خبر شوى يُو چې کله تاسو د مِصر نه تلئ نو مالِک خُدائ څنګه ستاسو په وړاندې بحرِقُلزم اوچ کړو. مونږ دا هم اورېدلى دى چې تاسو د اُردن نمرخاتۀ طرف ته د اموريانو دوه بادشاهان سيحون او عوج تباه کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5433, 'Joshua 2:11', 'Joshua', 2, 11, '&nbsp;کله چې مونږ د دې نه خبر شُو نو مونږ ډېر سخت ويرېدُو. ستاسو د يرې نه مونږ ټولو زړونه بائيللى وُو. مالِک خُدائ ستاسو خُدائ پاک بره په آسمان کښې او لاندې په زمکه هم خُدائ پاک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5434, 'Joshua 2:12', 'Joshua', 2, 12, '&nbsp;نو اوس بيا په مالِک خُدائ قسم وکړئ چې تاسو به زما خاندان سره داسې ښۀ سلوک کوئ لکه څنګه چې ما تاسو سره کړے دے. او ما سره څۀ ضمانت کېږدئ چې زۀ په تاسو باور وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5435, 'Joshua 2:13', 'Joshua', 2, 13, '&nbsp;ما سره وعده وکړئ چې تاسو به زما د مور پلار، وروڼو خوېندو او د هغوئ د کورَنو ژوند بچ کوئ او مونږ مۀ پرېږدئ چې ووژلے شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5436, 'Joshua 2:14', 'Joshua', 2, 14, '&nbsp;هغه جاسوسانو هغې ته ووئيل، ”کۀ مونږ د خپلې ژبې نه واوړېدو نو خُدائ پاک دې مونږ مړۀ کړى. کۀ تاسو څوک خبر نۀ کړل چې مونږ دلته څۀ کوُو، نو مونږ تاسو سره دا لوظ کوُو چې کله مالِک خُدائ مونږ له دا مُلک راکړى نو مونږ به تاسو سره ښۀ سلوک کوُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5437, 'Joshua 2:15', 'Joshua', 2, 15, '&nbsp;راحب چې په کوم کور کښې اوسېده د هغې دېوال د ښار د دېوال سره لګېدلے وو. نو هغې د کړکۍ نه د رسۍ په ذريعه سړى ښکته کوز کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5438, 'Joshua 2:16', 'Joshua', 2, 16, '&nbsp;هغې ورته ووئيل، ”هسې نه چې د بادشاه سړى مو پېدا کړى نو د غرونو مُلک ته لاړ شئ او هلته تر درېو ورځو پورې پټ شئ او کله چې د بادشاه سړى راواپس شى نو د هغې نه پس تاسو په خپله مخه تلے شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5439, 'Joshua 2:17', 'Joshua', 2, 17, '&nbsp;هغه سړو هغې ته ووئيل، ”مونږ به په يو شرط باندې په هغه وعده باندې قائم پاتې شُو کومه چې تا زمونږ نه اخستې ده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5440, 'Joshua 2:18', 'Joshua', 2, 18, '&nbsp;تۀ داسې وکړه چې کله مونږ ستاسو په مُلک حمله وکړُو نو تۀ په کړکۍ کښې دا سره رسۍ وتړه د کومې نه چې تۀ مونږ کوزوې. خپل مور پلار، وروڼه او د خپل پلار ټول خاندان کور ته دننه راوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5441, 'Joshua 2:19', 'Joshua', 2, 19, '&nbsp;خو کۀ څوک د کور نه وځى نو خُون به يې په خپله غاړه وى او مونږ به يې ذمه وار نۀ يُو. خو کۀ په کور کښې دننه چا ته څۀ ضرر ورسېدو نو بيا د هغۀ خُون زمونږ په غاړه دے او مونږ به يې ذمه وار يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5442, 'Joshua 2:20', 'Joshua', 2, 20, '&nbsp;خو کۀ چرې تۀ چا ته ووائې چې مونږ دلته څۀ کوُو نو چې کومه وعده تا زمونږ نه اخستې ده مونږ د هغې نه آزاد يُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5443, 'Joshua 2:21', 'Joshua', 2, 21, '&nbsp;راحب په دې رضا شوه او هغوئ يې رُخصت کړل. کله چې هغوئ لاړل نو هغې سره رسۍ د کړکۍ سره وتړله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5444, 'Joshua 2:22', 'Joshua', 2, 22, '&nbsp;جاسوسان غرونو ته لاړل او تر درېو ورځو پورې پټ وُو. د بادشاه سړو هغوئ په ټوله لار باندې لټول خو پېدا يې نۀ کړل نو هغوئ واپس يريحو ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5445, 'Joshua 2:23', 'Joshua', 2, 23, '&nbsp;بيا هغه دوه جاسوسان د غرونو نه راکوز شول، د سيند نه پورې وتل او واپس يشوَع د نون زوئ له لاړل. او چې څۀ شوى وُو هغه هر څۀ يې هغۀ ته ووئيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5446, 'Joshua 2:24', 'Joshua', 2, 24, '&nbsp;او بيا هغوئ ووئيل، ”زمونږ يقين دے چې مالِک خُدائ مونږ له هغه ټول مُلک راکړے دے او هلته ټول خلق زمونږ نه ډېر سخت يرېدلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5447, 'Joshua 3:1', 'Joshua', 3, 1, '&nbsp;په بل سحر يشوَع او ټول اِسرائيليان وختى پاڅېدل. او د شطيم کېمپ نه روان شول او اُردن ته لاړل او هلته يې خېمې ولګولې او انتظار يې کولو چې د هغه ځائ نه پورې غاړه واوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5448, 'Joshua 3:2', 'Joshua', 3, 2, '&nbsp;درې ورځې پس مشرانو په کېمپ کښې چکر لګولو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5449, 'Joshua 3:3', 'Joshua', 3, 3, '&nbsp;او خلقو ته يې حُکم ورکولو، ”کله چې تاسو وګورئ چې اِمامان د مالِک خُدائ ستاسو خُدائ پاک د لوظ صندوق اوړى نو د خپل ځائ نه پاڅئ او هغوئ پسې ځئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5450, 'Joshua 3:4', 'Joshua', 3, 4, '&nbsp;تاسو مخکښې هيڅکله دلته نۀ يئ راغلى نو هغوئ به تاسو ته د تلو لار ښائى. د لوظ صندوق ته مۀ ورنزدې کېږئ، دې نه تقريباً زر ګزه شاته اوسئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5451, 'Joshua 3:5', 'Joshua', 3, 5, '&nbsp;يشوَع خلقو ته وفرمائيل، ”ځانونه پاک کړئ ځکه چې مالِک خُدائ به سبا ستاسو په مينځ کښې لوئ کارونه کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5452, 'Joshua 3:6', 'Joshua', 3, 6, '&nbsp;بيا يشوَع اِمامانو ته وفرمائيل چې، ”د لوظ صندوق اوچت کړئ او دې سره د خلقو نه مخکښې ځئ.“ او څنګه چې هغۀ فرمائيلى وُو نو هغوئ هم هغه شان وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5453, 'Joshua 3:7', 'Joshua', 3, 7, '&nbsp;مالِک خُدائ يشوَع ته وفرمائيل، ”نن نه به زۀ د بنى اِسرائيلو په نظر کښې تا عزتمند کړم نو داسې به دوئ پوهه شى چې زۀ ستا هغه شان مل يم لکه څنګه چې د موسىٰ مل وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5454, 'Joshua 3:8', 'Joshua', 3, 8, '&nbsp;اِمامانو ته ووايه چې د لوظ صندوق اوړى او کله چې سيند ته ورسى نو دوئ دې د سيند غاړې ته ورکوز شى او هلته دې ودريږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5455, 'Joshua 3:9', 'Joshua', 3, 9, '&nbsp;بيا يشوَع خلقو ته وفرمائيل، ”دلته راشئ او چې مالِک خُدائ ستاسو خُدائ پاک تاسو ته څۀ فرمائى نو هغې ته غوږ ونيسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5456, 'Joshua 3:10', 'Joshua', 3, 10, '&nbsp;داسې به تاسو ته پته ولګى چې ژوندے خُدائ پاک ستاسو په مينځ کښې دے او کله چې تاسو مخ په وړاندې ځئ نو هغه به ضرور کنعانيان، حِتيان، حِويان، فرزيان، جرجاسيان، اموريان او يبوسيان ستاسو د مخې نه لرې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5457, 'Joshua 3:11', 'Joshua', 3, 11, '&nbsp;ګورئ چې د ټولې دُنيا د مالِک خُدائ د لوظ صندوق اُردن ته ستاسو په مخکښې تېرېدونکے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5458, 'Joshua 3:12', 'Joshua', 3, 12, '&nbsp;اوس دولس سړى چې د اِسرائيلو د هرې يوې قبيلې نه يو يو وى غوره کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5459, 'Joshua 3:13', 'Joshua', 3, 13, '&nbsp;اِمامان به د ټولې دُنيا د مالِک خُدائ د لوظ صندوق اوچتوى او کله چې هغوئ خپلې پښې په اوبو کښې کېږدى نو د اُردن سيند بهېدل به بند شى. او کومې اوبۀ چې ښکته راروانې وى هغه به د دېوال په شکل کښې يو ځائ کښې ودريږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5460, 'Joshua 3:16', 'Joshua', 3, 16, '&nbsp;نو د اوبو بهېدل بند شو. او لرې د آدم ښار په خوا کښې چې د ضرتان سره نزدې دے هلته اوبۀ د دېوال په شکل ودرېدې. او کومې اوبۀ چې لاندې د مالګې درياب ته بهېدې هغه په مکمله توګه بند شوې او خلق د يريحو سره نزدې پورې غاړه واوړېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5461, 'Joshua 3:17', 'Joshua', 3, 17, '&nbsp;اِمامان چې د مالِک خُدائ د لوظ صندوق يې اوچت کړے وو د اُردن سيند په مينځ کښې په اوچه زمکه تر هغې پورې ولاړ وُو چې د اِسرائيلو ټول خلق په اوچه زمکه باندې پورې غاړه اوړېدلى نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5462, 'Joshua 4:1', 'Joshua', 4, 1, '&nbsp;کله چې ټول قوم د اُردن د سيند نه واوړېدو نو مالِک خُدائ يشوَع ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5463, 'Joshua 4:2', 'Joshua', 4, 2, '&nbsp;”د دولسو قبيلو نه يو يو سړے خوښ کړه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5464, 'Joshua 4:3', 'Joshua', 4, 3, '&nbsp;او هغوئ له حُکم ورکړه چې د اُردن د سيند د مينځ نه دولس کاڼى راواخلى هم هغه ځائ نه چرته چې اِمامان ولاړ وُو، دوئ ته ووايه چې دا کاڼى د ځان سره يوسى او هلته يې کېږدى چرته به چې نن شپه خېمې لګوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5465, 'Joshua 4:4', 'Joshua', 4, 4, '&nbsp;بيا يشوَع هغه دولس سړى راوغوښتل کوم چې هغۀ د هرې يوې قبيلې نه خوښ کړى وُو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5466, 'Joshua 4:5', 'Joshua', 4, 5, '&nbsp;او ورته يې وفرمائيل، ”د مالِک خُدائ خپل خُدائ پاک د لوظ صندوق په وړاندې د اُردن سيند مينځ ته لاړ شئ. په تاسو کښې هر يو کس به يو يو کاڼے اوچتوى او د بنى اِسرائيلو د دولسو قبيلو دپاره به يو يو کاڼے په اوږه باندې اوړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5467, 'Joshua 4:6', 'Joshua', 4, 6, '&nbsp;دا کاڼى به خلقو ته رايادوى چې مالِک خُدائ څۀ کړى وُو. په راتلونکى وختونو کښې چې کله ستاسو ماشومان ستاسو نه تپوس کوى چې د دې کاڼو مطلب څۀ دے', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5468, 'Joshua 4:7', 'Joshua', 4, 7, '&nbsp;نو تاسو به ورته وايئ چې کله د مالِک خُدائ د لوظ صندوق هلته نه تېرېدو نو د اُردن سيند اوبۀ بهېدل بند شوى وُو. دا کاڼى به د همېشه دپاره د بنى اِسرائيلو يو يادګار وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5469, 'Joshua 4:8', 'Joshua', 4, 8, '&nbsp;سړو د يشوَع په حُکمونو عمل وکړو او څنګه چې مالِک خُدائ يشوَع ته حُکم کړے وو هغوئ د اُردن سيند مينځ نه دولس کاڼى واخستل د بنى اِسرائيلو د هرې يوې قبيلې دپاره يې يو يو اوچت کړو د خېمو ځائ ته يې يوړل او هلته يې کېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5470, 'Joshua 4:9', 'Joshua', 4, 9, '&nbsp;يشوَع د اُردن سيند په مينځ کښې د دولسو کاڼو يو بل يادګار ودرولو چرته چې د لوظ صندوق وړُونکى اِمامان ولاړ وُو. هغه کاڼى تر ننه پورې هلته دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5471, 'Joshua 4:10', 'Joshua', 4, 10, '&nbsp;هغه اِمامان چا چې د لوظ صندوق اوچت کړے وو د اُردن سيند په مينځ کښې تر هغې پورې ولاړ وُو چې خلقو هغه هر څۀ وکړل چې مالِک خُدائ يې يشوَع ته حُکم کړے وو، او څنګه چې موسىٰ هم د دې حُکم کړے وو. خلق په تېزۍ د سيند نه واوړېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5472, 'Joshua 4:11', 'Joshua', 4, 11, '&nbsp;کله چې هغوئ ټول بلې غاړې ته واوړېدل نو اِمامان چې د لوظ صندوق يې اوچت کړے وو د خلقو په مخکښې پورې وتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5473, 'Joshua 4:12', 'Joshua', 4, 12, '&nbsp;د موسىٰ د وېنا په مطابق د روبين، جاد او د منسى د نيمې قبيلې سړى د وسلې سره د نورو خلقو نه مخکښې روان وُو او پورې وتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5474, 'Joshua 4:13', 'Joshua', 4, 13, '&nbsp;تقريباً څلوېښت زره سړى سره د وسلې د مالِک خُدائ په حضور کښې يريحو سره نزدې مېدان ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5475, 'Joshua 4:14', 'Joshua', 4, 14, '&nbsp;په هغه ورځ مالِک خُدائ يشوَع د ټولو بنى اِسرائيلو په نظر کښې عزتمند کړو، هغوئ د هغۀ ټول عُمر هم هغه شان عزت کولو لکه چې څنګه يې د موسىٰ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5476, 'Joshua 4:15', 'Joshua', 4, 15, '&nbsp;بيا مالِک خُدائ يشوَع ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5477, 'Joshua 4:16', 'Joshua', 4, 16, '&nbsp;”هغه اِمامانو له حُکم ورکړه چا چې د لوظ صندوق اوچت کړے دے چې د اُردن د سيند نه بهر راوځى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
