(5479, 'Joshua 4:18', 'Joshua', 4, 18, '&nbsp;هغه اِمامان چې د مالِک خُدائ د لوظ صندوق يې اوچت کړے وو چې کله د سيند د تل نه اوچې زمکې ته راوختل نو د اُردن په سيند کښې اوبۀ روانې شوې او د مخکښې په شان په موج کښې بهېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5480, 'Joshua 4:19', 'Joshua', 4, 19, '&nbsp;د وړومبۍ مياشتې په لسمه ورځ خلق د اُردن سيند نه پورې وتل او په جِلجال کښې يې خېمې ولګولې چې د يريحو نمرخاتۀ طرف ته دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5481, 'Joshua 4:20', 'Joshua', 4, 20, '&nbsp;د اُردن سيند نه چې کوم دولس کاڼى اخستے شوى وُو نو يشوَع هلته ډېرے کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5482, 'Joshua 4:21', 'Joshua', 4, 21, '&nbsp;او بنى اِسرائيلو ته يې وفرمائيل، ”په راتلونکى وختونو کښې چې کله ستاسو بچى درنه تپوس وکړى چې د دې کاڼو مطلب څۀ دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5483, 'Joshua 4:22', 'Joshua', 4, 22, '&nbsp;نو تاسو به ورته د هغه وخت په حقله ووايئ چې کله بنى اِسرائيل د اُردن په سيند کښې په اوچه زمکه تېر شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5484, 'Joshua 4:23', 'Joshua', 4, 23, '&nbsp;هغوئ ته ووايئ چې مالِک خُدائ زمونږ خُدائ پاک د اُردن سيند تر هغې پورې اوچ کړے وو چې مونږ ترې نه واوړېدلو لکه څنګه چې هغۀ بحرِقُلزم تر هغې پورې اوچ کړے وو چې مونږ اوړېدلى نۀ وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5485, 'Joshua 4:24', 'Joshua', 4, 24, '&nbsp;او د دې په وجه به د دُنيا ټولو قومونو ته پته ولګى چې د مالِک خُدائ په لاس کښې قُدرت دے او تاسو به د مالِک خُدائ د خپل خُدائ پاک نه د همېشه دپاره يرېږئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5486, 'Joshua 5:1', 'Joshua', 5, 1, '&nbsp;د اُردن نمرپرېواتۀ طرف ته د اموريانو ټول بادشاهان او د مديترانى د سمندر په غاړه د کنعانيانو ټول بادشاهان خبر شول چې مالِک خُدائ د اُردن سيند تر هغې پورې اوچ کړے وو چې اِسرائيليان ترې نه واوړېدل هغوئ د بنى اِسرائيلو نه دومره ويرېدل چې مرګِ حال شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5487, 'Joshua 5:2', 'Joshua', 5, 2, '&nbsp;بيا مالِک خُدائ يشوَع ته وفرمائيل، ”د تېرو کاڼو نه چړې جوړې کړه او اِسرائيليان سنت کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5488, 'Joshua 5:3', 'Joshua', 5, 3, '&nbsp;نو يشوَع هم هغه شان وکړل څنګه چې مالِک خُدائ حُکم ورکړے وو او هغۀ اِسرائيليان په هغه ځائ کښې سنت کړل چې ورته د سنت غر وئيلے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5489, 'Joshua 5:7', 'Joshua', 5, 7, '&nbsp;د دغه سړو زامن هيڅکله سنت شوى نۀ وُو بلکې دا هغه نوے نسل وو کوم چې يشوَع سنت کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5490, 'Joshua 5:8', 'Joshua', 5, 8, '&nbsp;د سنت کېدو نه پس ټول نران تر هغې پورې په کېمپ کښې پاتې شُو چې روغ شوى نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5491, 'Joshua 5:9', 'Joshua', 5, 9, '&nbsp;مالِک خُدائ يشوَع ته وفرمائيل، ”نن ما تاسو په مِصر کښې د غلامۍ د شرم نه آزاد کړى يئ.“ او په دې وجه په هغه ځائ جِلجال نوم کېښودے شو چې تر نن ورځې پورې هم په هغه نوم ياديږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5492, 'Joshua 5:10', 'Joshua', 5, 10, '&nbsp;کله چې بنى اِسرائيلو د يريحو سره نزدې د جِلجال په مېدان باندې خېمې ولګولې نو هغوئ د هغې مياشتې د څوارلسمې ورځې په ماښام د فسحې اختر وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5493, 'Joshua 5:11', 'Joshua', 5, 11, '&nbsp;په ورپسې ورځ هغوئ په اول ځل هغه خوراک وکړو چې په کنعان کښې پېدا شوے وو يعنې وريتې دانې او پتيره روټۍ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5494, 'Joshua 5:12', 'Joshua', 5, 12, '&nbsp;چې بنى اِسرائيلو د هغه پېداوار په اول ځل وخوړو نو من پرې بند شول او نور من ورته نۀ مِلاوېدل. نو هم د هغه وخت نه هغوئ به هغه څۀ خوړل چې په کنعان کښې پېدا کېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5495, 'Joshua 5:13', 'Joshua', 5, 13, '&nbsp;يوه ورځ چې يشوَع يريحو سره نزدې وو نو ناڅاپه يې يو سړے تُوره په لاس مخې ته ولاړ وليدو. يشوَع ورنزدې شو او تپوس يې ترې نه وکړو، ”تۀ زمونږ ملګرے يې کۀ زمونږ دشمن يې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5496, 'Joshua 5:14', 'Joshua', 5, 14, '&nbsp;هغۀ جواب ورکړو، ”يو سره هم نۀ يم، زۀ د مالِک خُدائ د لښکر مشر يم.“ يشوَع په زمکه پړمخې پرېوتو او وې فرمائيل، ”صاحِبه زۀ ستا خِدمت کوونکے يم. تۀ څۀ غواړې چې زۀ يې وکړم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5497, 'Joshua 5:15', 'Joshua', 5, 15, '&nbsp;د مالِک خُدائ د لښکر مشر هغۀ ته وفرمائيل، ”څپلۍ وباسه ځکه چې تۀ په مقدسه زمکه ولاړ يې.“ او يشوَع هم هغه شان وکړل چې څۀ ورته فرمائيلے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5498, 'Joshua 6:1', 'Joshua', 6, 1, '&nbsp;نو د يريحو دروازې پخې بندې وساتلے شوې چې بنى اِسرائيليان ورننه نۀ وځى. نو د ښار نه نۀ څوک وتے شول او نۀ څوک ورننوتے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5499, 'Joshua 6:2', 'Joshua', 6, 2, '&nbsp;مالِک خُدائ يشوَع ته وفرمائيل، ”ما يريحو سره د هغې د بادشاه او سره د هغې د بهادرو سپاهيانو، تا ته حواله کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5500, 'Joshua 6:3', 'Joshua', 6, 3, '&nbsp;تۀ او ستا سپاهيان به روزانه تر شپږو ورځو پورې يو چکر د ښار نه ګېرچاپېره لګوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');